#!/usr/bin/env python3
"""Package genuine, already-built GNU Wasm binaries; runtime acceptance is separate."""
import argparse,hashlib,importlib.util,json,pathlib
q=argparse.ArgumentParser();q.add_argument('--name',choices=['gzip','grep','sed','wget','tar','findutils'],required=True);q.add_argument('--build',type=pathlib.Path,required=True);q.add_argument('--manifest',type=pathlib.Path,required=True);q.add_argument('--repo',type=pathlib.Path,required=True);q.add_argument('--private-key',type=pathlib.Path,required=True);q.add_argument('--work',type=pathlib.Path,required=True);a=q.parse_args();a.work.mkdir(parents=True,exist_ok=True)
record=next(r for r in json.loads(a.manifest.read_text()) if r['name']==a.name);version=record['version'];rel={'gzip':'gzip','grep':'src/grep','sed':'sed/sed','wget':'src/wget','tar':'src/tar','findutils':'find/find'}[a.name];program={'findutils':'find'}.get(a.name,a.name);binary=a.build/'build'/rel
with binary.open('rb')as f:
 if f.read(8)!=b'\0asm\x01\0\0\0':raise ValueError('native Wasm binary required')
def sha(p):
 with p.open('rb')as f:return hashlib.file_digest(f,'sha256').hexdigest()
limits={'gzip':'gzip compression, decompression and CRC checks; gzip/gunzip/zcat aliases.','grep':'GNU basic and extended regular expressions. PCRE support is disabled.','sed':'GNU substitutions, extended regular expressions and in-place editing.','wget':'GNU HTTP/HTTPS client using the native static OpenSSL build and system CA paths.','tar':'GNU uncompressed archive create/list/extract. External-compressor modes requiring fork are unsupported; use a separate gzip pipeline if the shell supports it.','findutils':'GNU find traversal and filtering. This package intentionally ships find only; xargs and fork-dependent -exec features are not accepted.'}[a.name]
doc=a.work/(a.name+'-README.txt');doc.write_text(f'GNU {a.name} {version} for wasm32 Linux\n\nThis is a genuine compiled GNU executable, not a BusyBox applet or browser JavaScript substitute. Use the explicit /usr/bin/{program} path when the shell gives BusyBox applets precedence.\n\nBuild scope: {limits}\nThe target has no fork/vfork. Compatibility functions return -1 with ENOSYS; no child-process success is fabricated. Runtime acceptance is recorded separately in tools/guest-packages/evidence and the release manifest.\n\nSource: {record["url"]}\nSource SHA256: {record["sha256"]}\nCorresponding port recipe: tools/guest-packages/build-gnu.py, no-fork.c and no-fork.h in the source checkpoint.\n')
source=a.build/'source'/(a.name+'-'+version);license=source/'COPYING';files={'usr/bin/'+program:{'path':str(binary),'mode':'755','sha256':sha(binary)},'usr/share/licenses/'+a.name+'/COPYING':{'path':str(license),'sha256':sha(license)},'usr/share/doc/'+a.name+'/README.linuxonweb':{'path':str(doc),'sha256':sha(doc)}}
if a.name=='gzip':
 for name in ['gunzip','zcat']:
  launcher=a.work/(name+'-launcher');text=(a.build/'build'/name).read_text();assert 'exec gzip ' in text;text=text.replace('exec gzip ','exec /usr/bin/gzip ');launcher.write_text(text);files['usr/bin/'+name]={'path':str(launcher),'mode':'755','sha256':sha(launcher)}
spec={'name':a.name,'version':version+'-r0','description':'GNU '+a.name+' native Linux/Wasm'+(' (find only)'if a.name=='findutils'else''),'url':'https://www.gnu.org/software/'+a.name+'/','license':'GPL-3.0-or-later','depends':['ca-certificates']if a.name=='wget'else[],'files':files,'provenance':{'source':record,'nativeSha256':sha(binary),'rebuiltThisTask':True,'runtimeAccepted':False,'scope':limits,'forkBehavior':'ENOSYS, never simulated success'}}
(a.work/(a.name+'-spec.json')).write_text(json.dumps(spec,indent=2)+'\n');logical=json.loads(json.dumps(spec))
for destination,item in logical['files'].items():
 if'path'in item:
  item['path']=program if destination=='usr/bin/'+program else destination.rsplit('/',1)[-1]+'-launcher' if a.name=='gzip' and destination in ['usr/bin/gunzip','usr/bin/zcat'] else a.name+'-COPYING'if destination.endswith('/COPYING')else a.name+'-README.txt'
here=pathlib.Path(__file__).resolve().parent;(here/'recipes'/(a.name+'.json')).write_text(json.dumps(logical,indent=2)+'\n');s=importlib.util.spec_from_file_location('apk_package',here/'package-apk.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m);print(json.dumps(m.package(spec,a.repo/'wasm32'/(a.name+'-'+version+'-r0.apk'),a.private_key,'linuxonweb-dev.rsa.pub')))
